import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int from, to, capacity, flow;
        public Edge(int from, int to, int capacity, int flow) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.flow = flow;
        }
    }

    static List<Edge> edges = new ArrayList<>();
    static List<Integer>[] graph = new ArrayList[100000];
    static int[][] dist1 = new int[31][31];
    static int[][] dist2 = new int[31][31];
    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {1, -1, 0, 0};
    static int n, t;
    static String[] a = new String[30];
    static String[] b = new String[30];
    static int whereX, whereY;
    static int source, sink;
    static int[] di = new int[100000], ptr = new int[100000], q = new int[100000];

    static {
        for (int i = 0; i < 100000; i++) {
            graph[i] = new ArrayList<>();
        }
    }

    static int readInt(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    static String readString(BufferedReader br) throws IOException {
        return br.readLine().trim();
    }

    static void addEdge(int u, int v, int cap) {
        edges.add(new Edge(u, v, cap, 0));
        graph[u].add(edges.size() - 1);
        edges.add(new Edge(v, u, 0, 0));
        graph[v].add(edges.size() - 1);
    }

    static boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    static void BFS1(int x, int y) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{x, y});
        for (int i = 0; i <= 20; ++i)
            for (int j = 0; j <= 20; ++j)
                dist1[i][j] = (int)1e9;
        dist1[x][y] = 0;
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int cx = cell[0], cy = cell[1];
            for (int i = 0; i < 4; ++i) {
                int nx = cx + dx[i], ny = cy + dy[i];
                if (isValid(nx, ny) && dist1[nx][ny] >= 1e9 && b[nx].charAt(ny) != 'Y') {
                    dist1[nx][ny] = dist1[cx][cy] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static boolean bfs() {
        Arrays.fill(di, -1);
        int head = 0, tail = 0;
        q[tail++] = source;
        di[source] = 0;
        while (head < tail && di[sink] == -1) {
            int v = q[head++];
            for (int id : graph[v]) {
                int to = edges.get(id).to;
                if (di[to] == -1 && edges.get(id).flow < edges.get(id).capacity) {
                    di[to] = di[v] + 1;
                    q[tail++] = to;
                }
            }
        }
        return di[sink] != -1;
    }

    static int dfs(int v, int flow) {
        if (flow == 0) return 0;
        if (v == sink) return flow;
        for (; ptr[v] < graph[v].size(); ++ptr[v]) {
            int id = graph[v].get(ptr[v]);
            int to = edges.get(id).to;
            if (di[to] != di[v] + 1) continue;
            int pushed = dfs(to, Math.min(flow, edges.get(id).capacity - edges.get(id).flow));
            if (pushed > 0) {
                edges.get(id).flow += pushed;
                edges.get(id ^ 1).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(source, (int)1e9)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static void BFS2(int x, int y) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{x, y});
        for (int i = 0; i <= 20; ++i)
            for (int j = 0; j <= 20; ++j)
                dist2[i][j] = (int)1e9;
        dist2[x][y] = 0;
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int cx = cell[0], cy = cell[1];
            if (dist2[cx][cy] >= dist1[cx][cy]) continue;
            for (int i = 0; i < 4; ++i) {
                int nx = cx + dx[i], ny = cy + dy[i];
                if (isValid(nx, ny) && dist2[nx][ny] >= 1e9 && a[nx].charAt(ny) != 'Y' && dist2[cx][cy] + 1 <= dist1[nx][ny]) {
                    dist2[nx][ny] = dist2[cx][cy] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        t = Integer.parseInt(br.readLine().trim());
        for (int i = 0; i < n; ++i) {
            a[i] = br.readLine().trim();
        }
        for (int i = 0; i < n; ++i) {
            b[i] = br.readLine().trim();
            for (int j = 0; j < n; ++j) {
                if (b[i].charAt(j) == 'Z') {
                    b[i] = b[i].substring(0, j) + 'Y' + b[i].substring(j + 1);
                    a[i] = a[i].substring(0, j) + 'Y' + a[i].substring(j + 1);
                    whereX = i;
                    whereY = j;
                }
            }
        }
        BFS1(whereX, whereY);
        source = 0;
        sink = 2 * n * n + 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i].charAt(j) == 'Y') continue;
                int inNode = i * n + j + 1;
                int outNode = n * n + i * n + j + 1;
                addEdge(source, inNode, a[i].charAt(j) - '0');
                addEdge(outNode, sink, b[i].charAt(j) - '0');
                BFS2(i, j);
                for (int ptx = 0; ptx < n; ++ptx) {
                    for (int pty = 0; pty < n; ++pty) {
                        if (b[ptx].charAt(pty) == 'Y' || dist2[ptx][pty] > t) continue;
                        addEdge(inNode, n * n + ptx * n + pty + 1, a[i].charAt(j) - '0');
                    }
                }
            }
        }
        System.out.println(maxFlow());
    }
}
